<script setup>import{ref,onMounted,computed}from'vue';import{api}from'../api';const list=ref([]),keyword=ref('');onMounted(async()=>list.value=await api.verifications());const rows=computed(()=>list.value.filter(x=>!keyword.value||[x.operatorName,x.itemSnapshot,String(x.memberId)].some(v=>v?.includes(keyword.value))))</script>
<template><div class="page-head"><div><h2>核销记录</h2><p>每次权益扣减均关联登录账号和现场核销人</p></div></div><div class="panel"><div class="toolbar"><el-input v-model="keyword" placeholder="会员 ID、权益或核销人" clearable style="width:280px"/></div><el-table :data="rows"><el-table-column prop="createdAt" label="核销时间" min-width="180"/><el-table-column prop="memberId" label="会员 ID"/><el-table-column prop="cardId" label="权益卡 ID"/><el-table-column prop="itemSnapshot" label="权益项目"/><el-table-column prop="quantity" label="扣减数量"/><el-table-column prop="operatorName" label="现场核销人"/><el-table-column prop="operatorMemberId" label="登录账号 ID"/></el-table></div></template>
